scwin.fn01 = function(val, val2, val3, va4) {
    if (val == 0 || val == "") {
        return "";
    } else {
        return val;
    }
};
scwin.titleFormatter = function(rowIndex, colIndex, value) {
    console.log(rowIndex + " : " + colIndex + " : " + value);
    return "title : " + dataList1.getCellData(rowIndex, "col2") + " 싶데요";
};
